import { NovelState } from '@prisma/client';

export interface NovelDetails {
  category: string[];
  coverUrl?: string;
  description: string;
  /** @description As of now this is the directory name inside the data folder */
  id: string;
  name: string;
  state: NovelState;
}
export interface INovel {
  id: string;
  name: string;
  category: string[];
  state: NovelState;
  /**
   * @description The ID generated by the Identity Provider
   * @example "230104087265432001"
   */
  ownerId: string;
  /** @description The `Writer` row the novel references; its `userId` is the `ownerId` above. */
  writerId: string;
  licenseId: string;
  coverUrl?: string;
  description: string;
  firstChapterCreatedAt?: Date;
}
